import manifest from '../data/imageManifest.json';
import { IMAGE_ALTS } from '../data/site.js';

// Responsive WebP from public/images (generated by `npm run images` from assets/EDITED PHOTOS).
export default function Img({ name, alt, sizes = '100vw', eager = false, pos, className, defaultWidth = 1200 }) {
  const meta = manifest[name];
  if (!meta) return null;
  const srcSet = meta.widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(', ');
  const fallback = meta.widths.includes(defaultWidth) ? defaultWidth : meta.widths[meta.widths.length - 1];
  return (
    <img
      className={className}
      src={`/images/${name}-${fallback}.webp`}
      srcSet={srcSet}
      sizes={sizes}
      width={meta.width}
      height={meta.height}
      alt={alt ?? IMAGE_ALTS[name] ?? ''}
      loading={eager ? 'eager' : 'lazy'}
      decoding="async"
      fetchPriority={eager ? 'high' : undefined}
      style={pos ? { objectPosition: pos } : undefined}
    />
  );
}
